package com.campusconnect.ui;
import com.campusconnect.model.User;import com.campusconnect.service.ItemService;import com.campusconnect.service.Session;
import javax.swing.*;import java.awt.*;
public class DashboardFrame extends JFrame {
    private final ItemService service=new ItemService();private final JPanel cards=new JPanel(new GridLayout(1,3,18,18));
    public DashboardFrame(){setTitle("CampusConnect | Dashboard");setSize(1100,700);setLocationRelativeTo(null);setDefaultCloseOperation(EXIT_ON_CLOSE);setLayout(new BorderLayout());
        JPanel side=new JPanel();side.setBackground(UiStyle.NAVY);side.setPreferredSize(new Dimension(230,700));side.setLayout(new BoxLayout(side,BoxLayout.Y_AXIS));JLabel logo=new JLabel("CampusConnect");logo.setForeground(Color.WHITE);logo.setFont(new Font("Arial",Font.BOLD,22));logo.setBorder(BorderFactory.createEmptyBorder(30,18,38,8));side.add(logo);
        String[] menus={"Dashboard","Browse Items","Report Lost Item","Report Found Item","My Claims","Admin Panel","Logout"};for(String m:menus){JButton b=new JButton(m);b.setMaximumSize(new Dimension(230,45));b.setAlignmentX(Component.CENTER_ALIGNMENT);b.setBackground(UiStyle.NAVY);b.setForeground(Color.WHITE);b.setBorderPainted(false);b.setFocusPainted(false);b.addActionListener(e->navigate(m));side.add(b);side.add(Box.createVerticalStrut(7));}add(side,BorderLayout.WEST);
        JPanel main=new JPanel(new BorderLayout(15,15));main.setBackground(UiStyle.BG);main.setBorder(BorderFactory.createEmptyBorder(30,35,30,35));User u=Session.getCurrentUser();JLabel title=new JLabel("Dashboard");title.setFont(new Font("Arial",Font.BOLD,30));JLabel welcome=new JLabel("Welcome, "+(u==null?"Student":u.getName())+"!");welcome.setFont(new Font("Arial",Font.PLAIN,16));JPanel header=new JPanel(new BorderLayout());header.setOpaque(false);JPanel labels=new JPanel();labels.setOpaque(false);labels.setLayout(new BoxLayout(labels,BoxLayout.Y_AXIS));labels.add(title);labels.add(Box.createVerticalStrut(8));labels.add(welcome);header.add(labels,BorderLayout.WEST);JButton refresh=UiStyle.primary("Refresh Statistics");refresh.addActionListener(e->loadStats());header.add(refresh,BorderLayout.EAST);main.add(header,BorderLayout.NORTH);
        cards.setOpaque(false);cards.setBorder(BorderFactory.createEmptyBorder(45,0,0,0));main.add(cards,BorderLayout.CENTER);add(main,BorderLayout.CENTER);loadStats();setVisible(true);
    }
    private void loadStats(){cards.removeAll();try{cards.add(card("Total Items",service.getTotalItems()));cards.add(card("Lost Items",service.getLostItemsCount()));cards.add(card("Found Items",service.getFoundItemsCount()));}catch(Exception e){cards.add(card("Total Items",0));cards.add(card("Lost Items",0));cards.add(card("Found Items",0));JOptionPane.showMessageDialog(this,e.getMessage(),"Dashboard error",JOptionPane.ERROR_MESSAGE);}cards.revalidate();cards.repaint();}
    private JPanel card(String label,int value){JPanel p=new JPanel(new GridLayout(2,1,5,5));p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(220,225,230)),BorderFactory.createEmptyBorder(25,20,25,20)));JLabel l=new JLabel(label);l.setForeground(UiStyle.MUTED);l.setFont(new Font("Arial",Font.PLAIN,17));JLabel v=new JLabel(String.valueOf(value));v.setForeground(UiStyle.BLUE);v.setFont(new Font("Arial",Font.BOLD,32));p.add(l);p.add(v);return p;}
    private void navigate(String menu){switch(menu){case "Dashboard"->loadStats();case "Browse Items"->new BrowseItemsFrame();case "Report Lost Item"->new ReportItemFrame("LOST");case "Report Found Item"->new ReportItemFrame("FOUND");case "My Claims"->new MyClaimsFrame();case "Admin Panel"->{if(Session.getCurrentUser()!=null&&"ADMIN".equals(Session.getCurrentUser().getRole()))new AdminPanelFrame();else JOptionPane.showMessageDialog(this,"Admin access only.");}case "Logout"->{int c=JOptionPane.showConfirmDialog(this,"Are you sure you want to logout?","Logout",JOptionPane.YES_NO_OPTION);if(c==JOptionPane.YES_OPTION){Session.clearSession();dispose();new LoginFrame();}}}}
}
